                "${caloriesSamples.size} calories samples"
            )

            // STUB: Return success
            ProcessResult(success = true, error = null)

        } catch (e: Exception) {
            android.util.Log.e("RustBridge", "Failed to process batch", e)
            ProcessResult(success = false, error = e.message)
