// Result types (match Rust uniffi types)

data class ProcessResult(
    val success: Boolean,
    val error: String?
)

data class HRVMetrics(
    val sdnn: Double,       // Standard deviation of NN intervals (ms)
    val rmssd: Double,      // Root mean square of successive differences (ms)
    val pnn50: Double,      // Percentage of NN intervals > 50ms different
    val sampleCount: Int
)

data class OutlierEvent(
    val timestamp: Long,
    val metricType: String,
    val value: Double,
    val zScore: Double      // Standard deviations from baseline
)

data class AlterBaseline(
    val alterId: String,
    val alterName: String,
    val metricType: String,
    val mean: Double,
    val std: Double,
    val percentile5: Double,
    val percentile95: Double,
    val sampleCount: Int
)

data class SyncResult(
    val success: Boolean,
    val uploadedSamples: Int,
    val error: String?
)
